import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {
    static long[] parent = new long[1100000];

    static long findSet(long x) {
        if (parent[(int) x] == x) return x;
        parent[(int) x] = findSet(parent[(int) x]);
        return parent[(int) x];
    }

    static void unionSets(long x, long y) {
        if (findSet(x) == findSet(y)) return;
        parent[(int) findSet(x)] = findSet(y);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        for (long i = 0; i < p; i++) {
            parent[(int) i] = i;
        }

        for (long i = 1; i < p; i++) {
            if ((k * i) % p != 0) {
                unionSets((k * i) % p, i);
            }
        }

        Set<Long> uniqueParents = new HashSet<>();
        for (long i = 1; i < p; i++) {
            uniqueParents.add(findSet(i));
        }

        long count = (k == 1) ? p : uniqueParents.size();

        long answer = 1;
        for (long i = 0; i < count; i++) {
            answer = (answer * p) % 1000000007;
        }

        System.out.println(answer);
        sc.close();
    }
}
